                    ],
                },
                {"indexed": True, "name": "tag", "type": "bytes32"},
            ],
        }
        _, decoded, _ = self._roundtrip(event_json, ((ADDR_A, 7), b"\x42" * 32))
        self.assertEqual(decoded, ((ADDR_A, 7), b"\x42" * 32))

    def test_dynamic_indexed_returns_raw_topic_on_decode(self):
